/* ===================== Admin panel ===================== */
function adminNav() { return [['home', 'activity', 'Overview'], ['requests', 'file', 'Requests'], ['assign', 'calendar', 'Assignments'], ['reviews', 'inventory', 'Report reviews'], ['disputes', 'flag', 'Disputes'], ['invoicing', 'invoice', 'Invoicing'], ['finance', 'pound', 'Finance'], ['pros', 'verified-pro', 'Pros'], ['training', 'training', 'Training'], ['clients', 'users', 'Clients'], ['properties', 'home', 'Properties'], ['policies', 'settings', 'Catalogue & policies'], ['audit', 'eye', 'Audit log'], ['settings', 'user', 'My settings']]; }
function jobsWhere(f) { return list('jobs').filter(f).sort(byNew); }
