  jobs.forEach(function (j) { cap += paidP(j); ref += refundedP(j); var s = settlement(j); if (s.status === 'PAID') paidOut += s.amountP; if (s.status === 'ELIGIBLE') payable += s.amountP; });
  var stale = jobs.filter(function (j) { return j.status === 'READY_FOR_ASSIGNMENT' && j.readyAt && hoursFrom(j.readyAt) < -24; });
