  h += '<div class="a-grid k3">' + stat('Requests', jobs.length) + stat('Captured (test)', P(cap)) + stat('Refunded', P(ref)) + stat('Pro payouts paid', P(paidOut)) + stat('Payouts payable', P(payable)) + stat('Pros to verify', pend.length) + '</div>';
  h += '<section class="a-sec"><h2>Work queues</h2><div class="a-grid" style="grid-template-columns:repeat(auto-fill,minmax(min(100%,220px),1fr))">' + queues().map(function (q, i) { return '<button class="a-card click a-queue" data-act="queue" data-q="' + i + '"' + (q[1].length ? '' : ' style="opacity:.6"') + '><span class="a-row sb"><span class="a-fine">' + ic(q[2], 16) + ' ' + esc(q[0]) + '</span><b class="num" style="font-size:24px">' + q[1].length + '</b></span></button>'; }).join('') + (pend.length ? '<button class="a-card click a-queue" data-go="pros"><span class="a-row sb"><span class="a-fine">' + ic('verified-pro', 16) + ' Pros to verify</span><b class="num" style="font-size:24px">' + pend.length + '</b></span></button>' : '') + '</div></section>';
  var ev = []; jobs.forEach(function (j) { (j.history || []).forEach(function (e) { ev.push({ e: e, j: j }); }); }); ev.sort(function (a, b) { return String(b.e.at).localeCompare(String(a.e.at)); });
